int gesture_feed(const struct imu_frame_s *frame, struct gesture_event_s *event)
{
  if (frame == NULL || event == NULL)
    {
      return -EINVAL;
    }

  event->type = GESTURE_NONE;

  /* ---- 阶段一：数据入环形缓冲 ---- */
  ring_write(frame);
  g_stat_frames++;

  /* ---- 阶段二：滑动窗口触发（每 10 帧 = 50ms 判定一次） ---- */
  g_frames_since_judge++;

  /* 缓冲未填满一个窗口时不做判定 */
  if (g_ring.count < GESTURE_WIN_FRAMES)
    {
      return 0;
    }

  if (g_frames_since_judge < GESTURE_STEP_FRAMES)
    {
      return 0;
    }

  g_frames_since_judge = 0;
  g_stat_windows++;

  /* ---- 阶段三~七：完整判定 ---- */
  if (classify_window(event))
    {
      /* 去重：距上次同类触发不足 250ms 则丢弃 */
      if (frame->timestamp_us != 0
          && g_last_type == event->type
          && (frame->timestamp_us - g_last_ts) < (GESTURE_DEBOUNCE_MS * 1000u))
        {
          event->type = GESTURE_NONE;
          return 0;
        }

      g_last_type = event->type;
      g_last_ts   = frame->timestamp_us;
      event->timestamp_us = frame->timestamp_us;
      g_stat_events++;
    }

  return 0;
}

