+/****************************************************************************
+ * 退出机制（真机实测新增）
+ * ==========================================================================
+ * 【问题背景】
+ * run_live() 是 while(1) 死循环，原版没有任何退出路径。
+ * 用户实测发现：程序跑起来后无法停止 —— 敲 Ctrl+C 只是往串口发了 0x03 字节，
+ * 程序不响应；再敲 `aura_demo` 也无法重新启动（旧实例还占着 IMU）。
+ * 唯一办法是拔插 USB 复位板子，严重影响调参效率。
+ *
+ * 【方案】在 live 循环里非阻塞读 stdin，检测到以下字符即退出：
+ *     q / Q / ESC(0x1b) / Ctrl+C(0x03) / Ctrl+D(0x04)
+ * 用 fcntl(O_NONBLOCK) 避免阻塞影响 208Hz 采样节奏。
+ ****************************************************************************/
+
+static int g_stdin_flags = -1;   /* 保存 stdin 原始 flags，退出时还原 */
+
+/* 把 stdin 设为非阻塞。返回 0 成功 */
+static int console_nonblock(void)
+{
+  int flags = fcntl(STDIN_FILENO, F_GETFL, 0);
+  if (flags < 0)
+    {
+      return -1;
+    }
+  g_stdin_flags = flags;
+  return fcntl(STDIN_FILENO, F_SETFL, flags | O_NONBLOCK);
+}
+
+/* 还原 stdin 为阻塞（退出前调用，否则 NSH 命令行会出问题） */
+static void console_restore(void)
+{
+  if (g_stdin_flags >= 0)
+    {
+      fcntl(STDIN_FILENO, F_SETFL, g_stdin_flags);
+      g_stdin_flags = -1;
+    }
+}
+
+/* 检查是否有退出键。返回 true = 请求退出（并已消费该字符） */
+static bool exit_key_pressed(void)
+{
+  unsigned char c;
+  int n = read(STDIN_FILENO, &c, 1);
+  if (n != 1)
+    {
+      return false;   /* 没有输入（EAGAIN），或出错 */
+    }
+
+  switch (c)
+    {
+      case 'q':
+      case 'Q':
+      case 0x1b:   /* ESC   */
+      case 0x03:   /* Ctrl+C */
+      case 0x04:   /* Ctrl+D */
+        return true;
+
+      default:
+        return false;
+    }
+}


