 * ==========================================================================
 * 存储三轴角速度，单读单写、容量 GESTURE_RINGBUF_FRAMES 帧。
 * 使用模运算下标，无需动态内存，适合嵌入式环境。
 ****************************************************************************/

static struct
{
  float    gx[GESTURE_RINGBUF_FRAMES];
  float    gy[GESTURE_RINGBUF_FRAMES];
  float    gz[GESTURE_RINGBUF_FRAMES];
  uint32_t ts[GESTURE_RINGBUF_FRAMES];
  uint32_t head;        /* 下一个写入位置 */
  uint32_t count;       /* 已写入总帧数（用于判断缓冲是否填满） */
} g_ring;

static uint32_t g_frames_since_judge;  /* 距离上次判定经过的帧数 */

═══ 2. ring_write / ring_get ═══
static void ring_write(const struct imu_frame_s *f)
{
  /* 写入时扣除陀螺零偏（真机实测新增）——
   * 放在这里而不是 compute_features，是为了让所有下游特征
   * （x_peak / y_mean / gyro_mag_peak / sustain_frames）都基于校正数据，
   * 避免「某几处扣了、某几处没扣」的不一致。
   * 未标定时 g_bias_* 全为 0，行为等同改动前。 */
  g_ring.gx[g_ring.head] = f->gyro_x - g_bias_x;
  g_ring.gy[g_ring.head] = f->gyro_y - g_bias_y;
  g_ring.gz[g_ring.head] = f->gyro_z - g_bias_z;
  g_ring.ts[g_ring.head] = f->timestamp_us;

  g_ring.head = (g_ring.head + 1) % GESTURE_RINGBUF_FRAMES;
  if (g_ring.count < GESTURE_RINGBUF_FRAMES)
    {
      g_ring.count++;
    }
}
---
 * 名称: ring_get
 * 描述: 读取环形缓冲中「倒数第 back 帧」的数据（back=0 为最新帧）
 ****************************************************************************/
static int ring_get(uint32_t back, float *gx, float *gy, float *gz, uint32_t *ts)
{
  uint32_t idx;

  if (back >= g_ring.count || back >= GESTURE_RINGBUF_FRAMES)
    {
      return -EINVAL;
    }

  idx = (g_ring.head + GESTURE_RINGBUF_FRAMES - 1 - back) % GESTURE_RINGBUF_FRAMES;

  if (gx) *gx = g_ring.gx[idx];
  if (gy) *gy = g_ring.gy[idx];
  if (gz) *gz = g_ring.gz[idx];
  if (ts) *ts = g_ring.ts[idx];
  return 0;
