+  static uint32_t stamps[TIMING_MAX_N];   /* 静态分配，避免大栈占用 */
+  int    got = 0;
+  int    i;
+
+  if (n_frames <= 0)      n_frames = 5000;
+  if (n_frames > TIMING_MAX_N) n_frames = TIMING_MAX_N;
+
+  printf("\n[TIMING] 采样抖动测量模式\n");
+  printf("[TIMING] 将连续采集 %d 帧（约 %.1f 秒），请保持板子静止\n\n",
+         n_frames, n_frames * 4.8f / 1000.0f);
+  printf("[TIMING] 采集中");
+
+  for (i = 0; i < n_frames; i++)
+    {
+      if (imu_sample(&f) != 0)
+        {
+          usleep(1000);
+          continue;
+        }
+      stamps[got++] = f.hw_timestamp;
+
+      if ((i % 500) == 0)
+        {
+          printf(".");
+        }
+      usleep(5000);   /* 按 208Hz 节拍 */
+    }
+  printf(" 完成\n\n");
+
+  if (got < 10)
+    {
+      printf("[TIMING] 采样点不足（%d），无法统计。\n", got);
+      return;
+    }
+
+  /* ---- 计算相邻间隔（处理 24 位回绕） ---- */
+  {
+    double  sum = 0.0, sumsq = 0.0;
+    float   dmin_ms = 1e9f, dmax_ms = 0.0f;
+    uint32_t prev = stamps[0];
+    int     n = 0;
+    float   dev_max = 0.0f;
+    float   mean;
+    float   sigma;
+
+    /* 分位数用的直方图（1 ms 一档，覆盖 0~20 ms） */
+    static int hist[24];
+    memset(hist, 0, sizeof(hist));
+
+    for (i = 1; i < got; i++)
+      {
+        uint32_t cur  = stamps[i];
+        uint32_t diff = (cur >= prev) ? (cur - prev)
+                                      : (cur + TIMING_WRAP_MASK + 1u - prev);
+        float diff_ms = (float)diff * TIMING_LSB_US / 1000.0f;
+
+        prev = cur;
+        n++;
+
+        sum   += diff_ms;
+        sumsq += (double)diff_ms * (double)diff_ms;
+
+        if (diff_ms < dmin_ms) dmin_ms = diff_ms;
+        if (diff_ms > dmax_ms) dmax_ms = diff_ms;
+
+        {
